(() => {
  'use strict';
  const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d'),mini=document.querySelector('#mini'),mctx=mini.getContext('2d');
  const $=s=>document.querySelector(s),clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const W=1800,H=1300; let dpr=1,camera={x:0,y:0},last=performance.now(),toastTimer=0,attackCooldown=0,skillCooldown=0,dodgeCooldown=0,shake=0,showMap=false,muted=false;
  const saved=(()=>{try{return JSON.parse(localStorage.getItem('auralis-save')||'{}')}catch{return {}}})();
  const player={x:840,y:645,hp:100,maxHp:100,energy:80,maxEnergy:80,level:saved.level||1,xp:saved.xp||0,coins:saved.coins??120,gems:saved.gems??2,damage:18,attack:0,dodge:0,walk:0,face:1,invuln:0,skill:'Ember',quests:saved.quests||0,kills:saved.kills||0,stats:saved.stats||{forca:0,maré:0,espirito:0},items:saved.items||['Lâmina de náufrago','Casaco de lona'],unlocked:saved.unlocked||1,daily:saved.daily||'',gear:saved.gear||false};
  const keys={}; let pointer={x:0,y:0,down:false}; let enemies=[],particles=[],floating=[],projectiles=[],interactTarget=null; const npcs=[{x:858,y:552,name:'Mira, faroleira',role:'história',icon:'✧'},{x:1054,y:727,name:'Timo, armeiro',role:'mercador',icon:'⚒'},{x:612,y:749,name:'Mestra Nalu',role:'treinadora',icon:'✦'}];
  const islands=[['Ilha do Farol','Nv. 1–8','⌂',true],['Atol das Conchas','Nv. 8–18','◉'],['Bosque Suspenso','Nv. 18–30','♧'],['Dunas de Vidro','Nv. 30–45','◇'],['Coroa Boreal','Nv. 45–60','❄'],['Fenda Sombria','Nv. 60–80','◐'],['Cume Trovejante','Nv. 80–105','ϟ'],['Olho da Tempestade','Nv. 105+','✦']];
  const enemyTypes=[{name:'Saqueador da maré',color:'#bc7563',hp:50,xp:28,coins:12,damage:8},{name:'Caranguejo de coral',color:'#db936b',hp:70,xp:35,coins:16,damage:9},{name:'Sentinela musgosa',color:'#73a884',hp:95,xp:55,coins:24,damage:12}];
  function spawnEnemy(type,x,y,boss=false){let t=enemyTypes[type%enemyTypes.length];return {x,y,homeX:x,homeY:y,type:type%enemyTypes.length,name:boss?'Guardião do Farol':t.name,color:boss?'#b68adf':t.color,hp:boss?380:t.hp,maxHp:boss?380:t.hp,xp:boss?250:t.xp,coins:boss?140:t.coins,damage:boss?16:t.damage,boss,alive:true,hit:0,attack:0,phase:Math.random()*6,respawn:0}}
  function populate(){enemies=[spawnEnemy(0,531,466),spawnEnemy(0,616,516),spawnEnemy(1,1205,581),spawnEnemy(0,1270,638),spawnEnemy(1,1127,967),spawnEnemy(2,1330,880),spawnEnemy(2,1385,960),spawnEnemy(0,440,890)];if(player.level>=5)enemies.push(spawnEnemy(2,1468,454,true))}
  populate();
  function save(){localStorage.setItem('auralis-save',JSON.stringify({level:player.level,xp:player.xp,coins:player.coins,gems:player.gems,quests:player.quests,kills:player.kills,stats:player.stats,items:player.items,unlocked:player.unlocked,daily:player.daily,gear:player.gear}))}
  function notify(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
  function updateHUD(){let next=player.level*100;$('#level').textContent=player.level;$('#hpText').textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;$('#energyText').textContent=`${Math.ceil(player.energy)} / ${player.maxEnergy}`;$('#xpText').textContent=`${player.xp} / ${next}`;$('#hpBar').style.width=`${100*player.hp/player.maxHp}%`;$('#energyBar').style.width=`${100*player.energy/player.maxEnergy}%`;$('#xpBar').style.width=`${100*player.xp/next}%`;$('#coins').textContent=player.coins;$('#gems').textContent=player.gems;$('#questCount').textContent=`${Math.min(player.quests,3)} / 3`;$('#questBar').style.width=`${Math.min(player.quests,3)/3*100}%`;$('#objective').textContent=player.quests>=3?'Volte até Mira, no farol':'Afaste os saqueadores da vila';$('#questTitle').textContent=player.quests>=3?'A luz volta a brilhar':'Um farol apagado';$('#questDesc').textContent=player.quests>=3?'Fale com Mira para receber sua recompensa.':'Ajude a vila: afaste os saqueadores da maré.';$('#dailyText').textContent=player.daily===new Date().toDateString()?'Você já coletou sua maré de hoje':'Sua recompensa está pronta';$('#dailyBtn').textContent=player.daily===new Date().toDateString()?'COLETADO':'COLETAR';$('#dailyBtn').disabled=player.daily===new Date().toDateString();}
  function levelUp(){while(player.xp>=player.level*100){player.xp-=player.level*100;player.level++;player.maxHp+=12;player.maxEnergy+=5;player.hp=player.maxHp;player.energy=player.maxEnergy;player.damage+=2;$('#levelUp').classList.add('show');setTimeout(()=>$('#levelUp').classList.remove('show'),2500);notify(`Nível ${player.level}! Você ficou mais forte.`);if(player.level===5){enemies.push(spawnEnemy(2,1468,454,true));notify('Uma presença antiga despertou na montanha!')}if(player.level>=8)player.unlocked=Math.max(player.unlocked,2)}save();}
  function addXP(n){player.xp+=n;levelUp();updateHUD()}
  function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(r.width*dpr);canvas.height=Math.floor(r.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}window.addEventListener('resize',resize);resize();
  function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
  function islandPath(){ctx.beginPath();ctx.moveTo(299,421);ctx.bezierCurveTo(320,335,404,289,520,302);ctx.bezierCurveTo(612,220,780,253,871,286);ctx.bezierCurveTo(1001,223,1161,265,1212,326);ctx.bezierCurveTo(1352,308,1484,390,1477,495);ctx.bezierCurveTo(1561,567,1513,684,1484,746);ctx.bezierCurveTo(1530,855,1443,973,1349,1003);ctx.bezierCurveTo(1294,1106,1150,1094,1064,1057);ctx.bezierCurveTo(960,1139,819,1084,750,1050);ctx.bezierCurveTo(627,1111,477,1053,437,986);ctx.bezierCurveTo(327,968,272,883,309,792);ctx.bezierCurveTo(228,714,267,594,309,549);ctx.bezierCurveTo(252,505,263,458,299,421);ctx.closePath()}
  function drawWorld(time){const vw=canvas.clientWidth,vh=canvas.clientHeight;if(!vw||!vh)return;ctx.clearRect(0,0,vw,vh);let scale=Math.min(vw/1130,vh/760);if(vw<650)scale=Math.min(vw/900,vh/620);const worldW=vw/scale,worldH=vh/scale;camera.x=clamp(player.x-worldW/2,0,W-worldW);camera.y=clamp(player.y-worldH/2,0,H-worldH);ctx.save();ctx.scale(scale,scale);ctx.translate(-camera.x,-camera.y);
    // Ocean with layered tide lines
    const ocean=ctx.createLinearGradient(0,0,W,H);ocean.addColorStop(0,'#1c6170');ocean.addColorStop(.45,'#155363');ocean.addColorStop(1,'#0d3d54');ctx.fillStyle=ocean;ctx.fillRect(camera.x,camera.y,worldW,worldH);
    for(let i=0;i<45;i++){let x=((i*197+time*.012)%2100)-150,y=((i*131+time*.008)%1500)-100;ctx.beginPath();ctx.ellipse(x,y,28+(i%4)*8,3,Math.sin(i)*.08,0,Math.PI*2);ctx.strokeStyle=`rgba(157,226,211,${.06+(i%3)*.02})`;ctx.lineWidth=2;ctx.stroke()}
    // Sand shore, green island, shadows
    ctx.save();ctx.shadowColor='#061e2b';ctx.shadowBlur=35;ctx.shadowOffsetY=16;islandPath();ctx.fillStyle='#c9ac78';ctx.fill();ctx.restore();islandPath();ctx.save();ctx.translate(0,-10);ctx.scale(.985,.985);ctx.translate(13,13);islandPath();let grass=ctx.createLinearGradient(350,300,1400,1050);grass.addColorStop(0,'#62966d');grass.addColorStop(.4,'#4e825f');grass.addColorStop(.72,'#467660');grass.addColorStop(1,'#356858');ctx.fillStyle=grass;ctx.fill();ctx.restore();
    // shoreline detail, paths
    for(let i=0;i<70;i++){let a=i*2.399,rr=1+(i%5)*7,x=850+Math.cos(a)*(510+rr),y=690+Math.sin(a)*(370+rr);ctx.beginPath();ctx.ellipse(x,y,8+(i%4)*2,3, a,0,Math.PI*2);ctx.fillStyle=i%2?'#ead29a':'#76b8a5';ctx.fill()}
    // winding sandy footpath
    ctx.beginPath();ctx.moveTo(852,579);ctx.bezierCurveTo(798,640,875,693,972,724);ctx.bezierCurveTo(1040,747,1010,819,1138,846);ctx.bezierCurveTo(1210,867,1232,947,1304,978);ctx.strokeStyle='#c8ad7b';ctx.lineWidth=35;ctx.lineCap='round';ctx.stroke();ctx.strokeStyle='#ddc795';ctx.lineWidth=23;ctx.stroke();
    ctx.beginPath();ctx.moveTo(837,585);ctx.bezierCurveTo(730,563,682,624,607,653);ctx.bezierCurveTo(532,682,529,760,446,794);ctx.strokeStyle='#c8ad7b';ctx.lineWidth=28;ctx.stroke();ctx.strokeStyle='#d9c18d';ctx.lineWidth=17;ctx.stroke();
    // village plaza
    ctx.beginPath();ctx.ellipse(916,667,146,101,-.1,0,Math.PI*2);ctx.fillStyle='#8c9a6b';ctx.fill();ctx.strokeStyle='#a5a775';ctx.lineWidth=2;ctx.stroke();
    // flowers & grass patches
    for(let i=0;i<130;i++){const x=340+(i*137)%1070,y=350+(i*193)%650;if((x>700&&x<1090&&y>590&&y<755)||(x>490&&x<670&&y>615&&y<670))continue;ctx.fillStyle=i%5===0?'#d8c874':i%4===0?'#d68d87':'#9dbb72';ctx.globalAlpha=.48;ctx.beginPath();ctx.arc(x,y,1.3+(i%3),0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
    // forest trees in clusters
    const trees=[[400,400],[455,390],[504,428],[554,383],[590,455],[458,510],[365,555],[382,617],[474,589],[524,532],[680,378],[741,402],[689,476],[760,496],[1320,437],[1370,481],[1410,540],[1350,581],[1432,633],[1320,715],[1387,759],[1450,830],[1395,886],[1303,925],[1229,1000],[1141,1009],[984,960],[924,1015],[756,949],[680,1020],[556,943],[474,889],[391,858],[339,772],[1452,702],[1190,394],[1125,366],[1070,398]];
    trees.forEach(([x,y],i)=>{let r=15+(i%4)*4;ctx.fillStyle='#304f43';ctx.beginPath();ctx.ellipse(x+7,y+11,r+6,r*.56,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#604d37';ctx.fillRect(x-3,y-3,6,16);ctx.fillStyle=['#36705b','#3e8061','#4b855f','#47765a'][i%4];ctx.beginPath();ctx.arc(x,y-8,r,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(x-r*.35,y-13,r*.62,0,Math.PI*2);ctx.fillStyle=['#478268','#55916c','#4f8665'][i%3];ctx.fill();ctx.fillStyle='#a5bd78';ctx.globalAlpha=.18;ctx.beginPath();ctx.arc(x-r*.35,y-16,r*.38,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1});
    // village huts
    const huts=[[777,635,'#bd9461'],[884,616,'#b77954'],[1000,654,'#c7a773'],[827,713,'#b78c5d']];huts.forEach(([x,y,col],i)=>{ctx.fillStyle='#3d5147';ctx.beginPath();ctx.ellipse(x+5,y+29,45,12,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#9e8a65';ctx.fillRect(x-31,y-6,62,34);ctx.fillStyle=col;ctx.beginPath();ctx.moveTo(x-42,y);ctx.lineTo(x,y-35-(i%2)*5);ctx.lineTo(x+42,y);ctx.closePath();ctx.fill();ctx.strokeStyle='#e2c992';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#314b4a';ctx.fillRect(x-7,y+9,14,19);ctx.fillStyle='#e5c27b';ctx.beginPath();ctx.arc(x+19,y+9,4,0,Math.PI*2);ctx.fill()});
    // lighthouse
    ctx.fillStyle='#263e45';ctx.beginPath();ctx.ellipse(848,527,50,14,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e3d3ad';ctx.beginPath();ctx.moveTo(823,528);ctx.lineTo(830,430);ctx.lineTo(866,430);ctx.lineTo(875,528);ctx.closePath();ctx.fill();ctx.fillStyle='#a96755';ctx.fillRect(831,447,34,8);ctx.fillRect(827,476,42,8);ctx.fillStyle='#e5c27b';ctx.beginPath();ctx.moveTo(824,431);ctx.lineTo(848,412);ctx.lineTo(872,431);ctx.closePath();ctx.fill();ctx.fillStyle='#f7e9ae';ctx.beginPath();ctx.arc(848,425,8,Math.PI,0);ctx.fill();ctx.globalAlpha=.14;ctx.beginPath();ctx.moveTo(850,423);ctx.lineTo(1110,345);ctx.lineTo(1060,529);ctx.closePath();ctx.fillStyle='#ffe9a7';ctx.fill();ctx.globalAlpha=1;
    // training ring and sea rocks
    ctx.beginPath();ctx.ellipse(603,757,61,33,0,0,Math.PI*2);ctx.strokeStyle='#dec797';ctx.lineWidth=6;ctx.stroke();for(const [x,y] of [[292,475],[1495,576],[318,926],[1426,1022],[1121,299],[690,299],[1240,301],[580,1044],[1509,726],[354,671]]){ctx.fillStyle='#557d78';ctx.beginPath();ctx.ellipse(x,y,17,10,.4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#82a698';ctx.beginPath();ctx.ellipse(x-4,y-4,9,4,.4,0,Math.PI*2);ctx.fill()}
    // glimmer secret cave
    ctx.fillStyle='#253f42';ctx.beginPath();ctx.moveTo(1402,925);ctx.lineTo(1420,891);ctx.lineTo(1445,925);ctx.closePath();ctx.fill();ctx.fillStyle='#64dfcd';ctx.globalAlpha=.65+Math.sin(time*.004)*.25;ctx.beginPath();ctx.arc(1421,923,5,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
    // entities
    for(const n of npcs)drawNPC(n,time);for(const e of enemies)if(e.alive)drawEnemy(e,time);drawPlayer(time);drawParticles();ctx.restore();drawMini();
  }
  function drawNPC(n,t){let bob=Math.sin(t*.003+n.x)*2;ctx.fillStyle='#112d35';ctx.beginPath();ctx.ellipse(n.x,n.y+15,13,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=n.role==='história'?'#9bd8bd':n.role==='mercador'?'#e1ba7d':'#94b8e4';ctx.beginPath();ctx.arc(n.x,n.y-4+bob,9,0,Math.PI*2);ctx.fill();ctx.fillStyle='#c8d6c6';ctx.fillRect(n.x-7,n.y+4+bob,14,16);ctx.fillStyle='#e9d39b';ctx.beginPath();ctx.arc(n.x,n.y-7+bob,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff0bb';ctx.font='bold 11px DM Sans';ctx.textAlign='center';ctx.fillText('✦',n.x,n.y-24+bob);ctx.fillStyle='#e3f2e7';ctx.font='10px DM Sans';ctx.fillText(n.name,n.x,n.y+34)}
  function drawEnemy(e,t){let bob=Math.sin(t*.004+e.phase)*2;ctx.fillStyle='#16313a';ctx.beginPath();ctx.ellipse(e.x,e.y+13,e.boss?19:13,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=e.hit>0?'#fff':e.color;ctx.beginPath();ctx.arc(e.x,e.y-2+bob,e.boss?17:11,0,Math.PI*2);ctx.fill();ctx.fillStyle=e.boss?'#563d78':'#755347';ctx.fillRect(e.x-(e.boss?11:8),e.y+5+bob,e.boss?22:16,14);ctx.fillStyle='#f0d4a3';ctx.beginPath();ctx.arc(e.x-4,e.y-4+bob,2,0,Math.PI*2);ctx.arc(e.x+4,e.y-4+bob,2,0,Math.PI*2);ctx.fill();if(e.boss){ctx.fillStyle='#f1d27f';ctx.font='bold 9px DM Sans';ctx.textAlign='center';ctx.fillText('BOSS · GUARDIÃO',e.x,e.y-29);ctx.fillStyle='#23343c';ctx.fillRect(e.x-28,e.y-24,56,4);ctx.fillStyle='#e68d9a';ctx.fillRect(e.x-28,e.y-24,56*e.hp/e.maxHp,4)}if(e.hp<e.maxHp){ctx.fillStyle='#172c35';ctx.fillRect(e.x-14,e.y-20,28,3);ctx.fillStyle='#ef897c';ctx.fillRect(e.x-14,e.y-20,28*e.hp/e.maxHp,3)}}
  function drawPlayer(t){let bob=Math.sin(t*.012)*1.5;ctx.fillStyle='#0a2733';ctx.beginPath();ctx.ellipse(player.x,player.y+16,13,6,0,0,Math.PI*2);ctx.fill();if(player.invuln>0&&Math.floor(t/65)%2)ctx.globalAlpha=.45;ctx.fillStyle=player.dodge>0?'#bdebd3':'#d5e0d0';ctx.beginPath();ctx.arc(player.x,player.y-5+bob,9,0,Math.PI*2);ctx.fill();ctx.fillStyle='#57a891';ctx.fillRect(player.x-8,player.y+3+bob,16,16);ctx.fillStyle='#eed19a';ctx.beginPath();ctx.arc(player.x+player.face*3,player.y-8+bob,5,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#e5ca87';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(player.x+player.face*8,player.y+7);ctx.lineTo(player.x+player.face*17,player.y-1);ctx.stroke();ctx.globalAlpha=1;if(player.attack>0){ctx.strokeStyle=`rgba(240,219,153,${player.attack*2})`;ctx.lineWidth=4;ctx.beginPath();ctx.arc(player.x+player.face*9,player.y,29,-1.15,1.15);ctx.stroke()}}
  function drawParticles(){for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;for(const f of floating){ctx.globalAlpha=Math.max(0,f.life/f.max);ctx.fillStyle=f.color;ctx.font='bold 13px DM Sans';ctx.textAlign='center';ctx.fillText(f.text,f.x,f.y)}ctx.globalAlpha=1;for(const p of projectiles){ctx.shadowColor=p.color;ctx.shadowBlur=15;ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,8,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}}
  function drawMini(){mctx.clearRect(0,0,140,100);mctx.fillStyle='#164854';mctx.fillRect(0,0,140,100);mctx.fillStyle='#638d67';mctx.beginPath();mctx.ellipse(70,50,49,35,-.1,0,Math.PI*2);mctx.fill();mctx.fillStyle='#d0b77e';mctx.fillRect(59,42,30,17);mctx.fillStyle='#e9d49c';mctx.fillRect(65,32,8,10);mctx.fillStyle='#77e2c2';mctx.beginPath();mctx.arc(70+(player.x-850)*.05,50+(player.y-690)*.05,3,0,Math.PI*2);mctx.fill();for(const e of enemies)if(e.alive){mctx.fillStyle=e.boss?'#da85d1':'#d98a78';mctx.fillRect(70+(e.x-850)*.05-1,50+(e.y-690)*.05-1,3,3)}}
  function emit(x,y,color,n=12){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=20+Math.random()*100;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,size:2+Math.random()*3,color,life:.35+Math.random()*.35,max:.7})}}
  function nearestEnemy(range=100){return enemies.filter(e=>e.alive&&Math.hypot(e.x-player.x,e.y-player.y)<range).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0]}
  function damageEnemy(e,damage){if(!e?.alive)return;e.hp-=damage;e.hit=.12;emit(e.x,e.y-5,e.boss?'#cba5f3':'#f1cb85',8);floating.push({x:e.x,y:e.y-22,text:`-${damage}`,color:'#ffe0a6',life:.8,max:.8});shake=4;if(e.hp<=0){e.alive=false;emit(e.x,e.y,'#8de1be',22);player.coins+=e.coins;player.kills++;addXP(e.xp);notify(`${e.name} derrotado · +${e.xp} XP · +${e.coins} conchas`);if(player.quests<3&&e.type===0)player.quests++;if(e.boss){player.gems++;player.items.push('Fragmento da Aurora');notify('CHEFE DERROTADO · Fragmento da Aurora obtido!')}setTimeout(()=>{if(!e.boss){let t=enemyTypes[e.type];Object.assign(e,{alive:true,hp:e.maxHp,x:e.homeX,y:e.homeY})}},12000);save();updateHUD()}}
  function attack(){if(attackCooldown>0)return;attackCooldown=.42;player.attack=.19;let e=nearestEnemy(91);if(e){damageEnemy(e,player.damage+Math.floor(player.stats.forca*2));player.face=e.x>player.x?1:-1}else{emit(player.x+player.face*34,player.y,'#c5dfd1',4)}}
  function castSkill(){if(skillCooldown>0)return;if(player.energy<20){notify('Vigor insuficiente');return}player.energy-=20;skillCooldown=3.2;updateHUD();let e=nearestEnemy(420);let tx=e?e.x:player.x+player.face*160,ty=e?e.y:player.y;projectiles.push({x:player.x,y:player.y,vx:(tx-player.x)/Math.max(1,Math.hypot(tx-player.x,ty-player.y))*370,vy:(ty-player.y)/Math.max(1,Math.hypot(tx-player.x,ty-player.y))*370,life:1.2,color:'#ff9a67',damage:42+player.level*2});emit(player.x,player.y,'#ffb16e',14);notify('Brasa errante!')}
  function dodge(){if(dodgeCooldown>0||player.energy<12)return;player.energy-=12;dodgeCooldown=1.1;player.dodge=.24;player.invuln=.38;player.x=clamp(player.x+player.face*90,300,1500);emit(player.x,player.y,'#8ae3cc',10);updateHUD()}
  function interact(){if(interactTarget){if(interactTarget.role==='história'){if(player.quests>=3){player.quests=0;player.coins+=45;addXP(80);player.unlocked=Math.max(player.unlocked,2);notify('Missão concluída! +80 XP · +45 conchas · Atol descoberto');save();updateHUD()}else openModal('dialogue')}else if(interactTarget.role==='mercador')openModal('shop');else openModal('skills');return}const secret=Math.hypot(player.x-1421,player.y-923);if(secret<55){player.gems++;player.coins+=30;player.items.push('Lágrima do mar');notify('Segredo descoberto: Lágrima do mar!');emit(1421,923,'#67f0de',35);player.x=1350;save();updateHUD()}}
