function drawNPC(n,t){let bob=Math.sin(t*.003+n.x)*2;x.fillStyle='#112d35';x.beginPath();x.ellipse(n.x,n.y+15,13,5,0,0,7);x.fill();x.fillStyle=n.role==='história'?'#9bd8bd':n.role==='mercador'?'#e1ba7d':'#94b8e4';x.beginPath();x.arc(n.x,n.y-4+bob,9,0,7);x.fill();x.fillStyle='#c8d6c6';x.fillRect(n.x-7,n.y+4+bob,14,16);x.fillStyle='#e9d39b';x.beginPath();x.arc(n.x,n.y-7+bob,5,0,7);x.fill();x.fillStyle='#fff0bb';x.font='bold 11px sans-serif';x.textAlign='center';x.fillText('✦',n.x,n.y-24+bob);x.fillStyle='#e3f2e7';x.font='10px sans-serif';x.fillText(n.name,n.x,n.y+34)}
function drawEnemy(e,t){let bob=Math.sin(t*.004+e.phase)*2;x.fillStyle='#16313a';x.beginPath();x.ellipse(e.x,e.y+13,e.boss?19:13,5,0,0,7);x.fill();x.fillStyle=e.hit>0?'#fff':e.color;x.beginPath();x.arc(e.x,e.y-2+bob,e.boss?17:11,0,7);x.fill();x.fillStyle=e.boss?'#563d78':'#755347';x.fillRect(e.x-8,e.y+5+bob,16,14);x.fillStyle='#f0d4a3';x.beginPath();x.arc(e.x-4,e.y-4+bob,2,0,7);x.arc(e.x+4,e.y-4+bob,2,0,7);x.fill();if(e.boss){x.fillStyle='#f1d27f';x.font='bold 9px sans-serif';x.textAlign='center';x.fillText('BOSS · GUARDIÃO',e.x,e.y-29)}if(e.hp<e.max){x.fillStyle='#172c35';x.fillRect(e.x-14,e.y-20,28,3);x.fillStyle='#ef897c';x.fillRect(e.x-14,e.y-20,28*e.hp/e.max,3)}}
function drawPlayer(t){let bob=Math.sin(t*.012)*1.5;x.fillStyle='#0a2733';x.beginPath();x.ellipse(p.x,p.y+16,13,6,0,0,7);x.fill();if(p.invuln>0&&Math.floor(t/65)%2)x.globalAlpha=.4;x.fillStyle='#d5e0d0';x.beginPath();x.arc(p.x,p.y-5+bob,9,0,7);x.fill();x.fillStyle='#57a891';x.fillRect(p.x-8,p.y+3+bob,16,16);x.fillStyle='#eed19a';x.beginPath();x.arc(p.x+p.face*3,p.y-8+bob,5,0,7);x.fill();x.strokeStyle='#e5ca87';x.lineWidth=3;x.beginPath();x.moveTo(p.x+p.face*8,p.y+7);x.lineTo(p.x+p.face*17,p.y-1);x.stroke();x.globalAlpha=1;if(p.attack>0){x.strokeStyle=`rgba(240,219,153,${p.attack*3})`;x.lineWidth=4;x.beginPath();x.arc(p.x+p.face*9,p.y,29,-1.15,1.15);x.stroke()}}
function drawFx(){for(const q of particles){x.globalAlpha=Math.max(0,q.life/q.max);x.fillStyle=q.color;x.beginPath();x.arc(q.x,q.y,q.size,0,7);x.fill()}x.globalAlpha=1;for(const f of floats){x.globalAlpha=Math.max(0,f.life/f.max);x.fillStyle=f.color;x.font='bold 13px sans-serif';x.textAlign='center';x.fillText(f.text,f.x,f.y)}x.globalAlpha=1;for(const q of shots){x.shadowColor=q.color;x.shadowBlur=15;x.fillStyle=q.color;x.beginPath();x.arc(q.x,q.y,8,0,7);x.fill();x.shadowBlur=0}}
