function burst(a,b,col,n=12){for(let i=0;i<n;i++){let ang=Math.random()*7,s=20+Math.random()*100;particles.push({x:a,y:b,vx:Math.cos(ang)*s,vy:Math.sin(ang)*s,size:2+Math.random()*3,color:col,life:.35+Math.random()*.35,max:.7})}}function nearEnemy(range=100){return enemies.filter(e=>e.alive&&Math.hypot(e.x-p.x,e.y-p.y)<range).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0]}
function hurt(e,d){if(!e||!e.alive)return;e.hp-=d;e.hit=.12;burst(e.x,e.y-5,e.boss?'#cba5f3':'#f1cb85',8);floats.push({x:e.x,y:e.y-22,text:`-${d}`,color:'#ffe0a6',life:.8,max:.8});if(e.hp<=0){e.alive=false;burst(e.x,e.y,'#8de1be',22);p.coins+=e.coins;p.kills++;addXP(e.xp);notify(`${e.name} derrotado · +${e.xp} XP · +${e.coins} conchas`);if(p.quests<3&&e.type===0)p.quests++;if(e.boss){p.gems++;p.items.push('Fragmento da Aurora');notify('CHEFE DERROTADO · Fragmento da Aurora!')}setTimeout(()=>{if(!e.boss){e.alive=true;e.hp=e.max;e.x=e.hx;e.y=e.hy}},12000);save();hud()}}
function attack(){if(cd>0)return;cd=.42;p.attack=.19;let e=nearEnemy(91);if(e){p.face=e.x>p.x?1:-1;hurt(e,p.damage+(p.stats.forca||0)*2)}else burst(p.x+p.face*34,p.y,'#c5dfd1',4)}function cast(){if(skillCD>0)return;if(p.energy<20){notify('Vigor insuficiente');return}p.energy-=20;skillCD=3.2;hud();let e=nearEnemy(420),tx=e?e.x:p.x+p.face*160,ty=e?e.y:p.y,d=Math.hypot(tx-p.x,ty-p.y)||1;shots.push({x:p.x,y:p.y,vx:(tx-p.x)/d*370,vy:(ty-p.y)/d*370,life:1.2,color:'#ff9a67',damage:42+p.level*2});burst(p.x,p.y,'#ffb16e',14);notify('Brasa errante!')}
function dodge(){if(dodgeCD>0||p.energy<12)return;p.energy-=12;dodgeCD=1.1;p.dodge=.24;p.invuln=.38;p.x=Math.max(290,Math.min(1510,p.x+p.face*90));burst(p.x,p.y,'#8ae3cc',10);hud()}

