function dodge(){if(dodgeCD>0||p.energy<12)return;p.energy-=12;dodgeCD=1.1;p.dodge=.24;p.invuln=.38;p.x=Math.max(290,Math.min(1510,p.x+p.face*90));burst(p.x,p.y,'#8ae3cc',10);hud()}

// Persisted progression and interface
p.island=Math.max(0,Math.min(islands.length-1,saved.island||0));p.questClaimed=!!saved.questClaimed;
function save(){try{localStorage.setItem('auralis-save',JSON.stringify({level:p.level,xp:p.xp,coins:p.coins,gems:p.gems,quests:p.quests,kills:p.kills,stats:p.stats,items:p.items,unlocked:p.unlocked,daily:p.daily,island:p.island,questClaimed:p.questClaimed}))}catch(e){console.warn('Não foi possível salvar o progresso',e)}}
function hud(){let n=p.level*100;$('#level').textContent=p.level;$('#hpText').textContent=`${Math.ceil(p.hp)} / ${p.max}`;$('#energyText').textContent=`${Math.ceil(p.energy)} / ${p.maxEnergy}`;$('#xpText').textContent=`${p.xp} / ${n}`;$('#hpBar').style.width=100*p.hp/p.max+'%';$('#energyBar').style.width=100*p.energy/p.maxEnergy+'%';$('#xpBar').style.width=Math.min(100,100*p.xp/n)+'%';$('#coins').textContent=p.coins;$('#gems').textContent=p.gems;$('#questCount').textContent=`${Math.min(3,p.quests)} / 3`;$('#questBar').style.width=Math.min(3,p.quests)/3*100+'%';let done=p.questClaimed;$('#objective').textContent=done?'Explore a enseada e fique mais forte':p.quests>=3?'Volte até Mira, no farol':'Afaste os saqueadores da vila';$('#questTitle').textContent=done?'A luz voltou a brilhar':p.quests>=3?'A luz volta a brilhar':'Um farol apagado';$('#questDesc').textContent=done?'A vila está segura. Continue sua jornada pelo arquipélago.':p.quests>=3?'Fale com Mira para receber sua recompensa.':'Ajude a vila: afaste os saqueadores da maré.';$('#dailyText').textContent=p.daily===new Date().toDateString()?'Você já coletou sua maré de hoje':'Sua recompensa está pronta';$('#dailyBtn').textContent=p.daily===new Date().toDateString()?'COLETADO':'COLETAR';$('#dailyBtn').disabled=p.daily===new Date().toDateString();let island=islands[p.island];$('.island-label strong').textContent=island[0].toUpperCase();$('.island-label small').textContent=`ARQUIPÉLAGO DE LÚMEN · REGIÃO ${String(p.island+1).padStart(2,'0')}`;$('#locationName').textContent=p.island===0?'ENSEADA DO FAROL':island[0].toUpperCase();$('.location small').textContent=`${island[0]} · ${island[1]}`;let discover=$('.discover-card .section-title span');if(discover)discover.textContent=`${p.unlocked.toString().padStart(2,'0')} / 08`;let next=$('.next-island small');if(next)next.textContent=p.unlocked<8?`${islands[p.unlocked][0]} · ${islands[p.unlocked][1].replace('Nv. ','Nv. ')}`:'Todas as ilhas descobertas';$('.crew-level').textContent=String(p.level).padStart(2,'0');$('#dailyBtn').setAttribute('aria-label',p.daily===new Date().toDateString()?'Recompensa diária coletada':'Coletar recompensa diária')}
const backdrop=$('#modalBackdrop'),content=$('#modalContent');let nearestNpc=null,muted=false;
function openModal(markup){content.innerHTML=markup;backdrop.classList.add('open');backdrop.setAttribute('aria-hidden','false')}
function closeModal(){backdrop.classList.remove('open');backdrop.setAttribute('aria-hidden','true')}
function modalHead(kicker,title,lead){return `<small class="modal-kicker">${kicker}</small><h2>${title}</h2><p class="modal-lead">${lead}</p>`}
function showMap(){let cards=islands.map((is,i)=>`<button class="island-option ${i>=p.unlocked?'locked':''}" data-island="${i}" ${i>=p.unlocked?'disabled':''}><span class="island-emoji">${is[2]}</span><span><b>${is[0]}</b><small>${is[1]} · ${i<p.unlocked?'Descoberta':'Ainda desconhecida'}</small></span></button>`).join('');openModal(`${modalHead('CARTOGRAFIA DE AURALIS','Mapa do mar','As rotas aparecem conforme você ganha experiência. A enseada é o primeiro trecho explorável deste protótipo.') }<div class="island-grid">${cards}</div>`)}
function showInventory(){let cards=p.items.map((item,i)=>`<div class="item-card"><span class="item-icon">${i===0?'⚔':i===1?'◇':'✦'}</span><span><b>${item}</b><small>${i===0?'Arma · dano base '+p.damage:i===1?'Traje de viajante':'Item raro de missão'}</small></span></div>`).join('');openModal(`${modalHead('PERTENCES','Mochila',`${p.items.length} itens · equipamento e lembranças da sua jornada.`)}<div class="item-list">${cards||'<p class="modal-lead">Sua mochila está vazia.</p>'}</div><button class="modal-action" data-action="rest">DESCANSAR · 15 CONCHAS</button>`)}
function showSkills(){openModal(`${modalHead('TÉCNICAS DE COMBATE','Poderes','Domine o ritmo da maré. O vigor se recupera aos poucos durante a exploração.')}<div class="skill-list"><div class="skill-card"><b>⚔ Golpe leve</b><small>Dano ${p.damage+(p.stats.forca||0)*2} · alcance curto</small></div><div class="skill-card"><b>✦ Brasa errante</b><small>20 vigor · projétil mágico</small></div><div class="skill-card"><b>⇢ Passo da maré</b><small>12 vigor · esquiva e breve invulnerabilidade</small></div><div class="skill-card"><b>◈ Afinidades</b><small>Força ${p.stats.forca||0} · Maré ${p.stats.maré||0} · Espírito ${p.stats.espirito||0}</small></div></div><button class="modal-action" data-action="train">TREINAR COM NALU</button>`)}
function showShop(){openModal(`${modalHead('MERCADO DA ENSEADA','Balcão de Timo','Troque conchas por itens úteis. Os aprimoramentos ficam salvos neste navegador.')}<div class="stat-upgrades"><div class="upgrade-row"><span>Poção de maré · recupera 45 vida</span><button data-buy="potion">35 ◉ COMPRAR</button></div><div class="upgrade-row"><span>Lâmina de coral · +8 dano</span><button data-buy="blade" ${p.items.includes('Lâmina de coral')?'disabled':''}>110 ◉ COMPRAR</button></div><div class="upgrade-row"><span>Bolsa de vigor · +15 vigor máximo</span><button data-buy="vigor">90 ◉ COMPRAR</button></div></div>`)}
function train(){let cost=45+((p.stats.forca||0)+(p.stats.maré||0)+(p.stats.espirito||0))*30;if(p.coins<cost){notify(`Faltam conchas: treinamento custa ${cost}.`);return}p.coins-=cost;p.stats.forca=(p.stats.forca||0)+1;p.damage+=2;save();hud();showSkills();notify('Nalu ensinou você a golpear com mais força!')}
function interact(n=nearestNpc){if(!n){notify('Ninguém por perto. Aproxime-se de um personagem.');return}if(n.role==='história'){if(p.quests>=3&&!p.questClaimed){p.questClaimed=true;p.coins+=45;addXP(80);save();hud();notify('Missão concluída · +80 XP · +45 conchas');openModal(`${modalHead('MISSÃO CONCLUÍDA','A luz voltou','Mira agradece sua coragem. O farol está aceso novamente!')}<button class="modal-action" data-action="map">VER ROTAS DO ARQUIPÉLAGO</button>`)}else openModal(`${modalHead('MIRA · FAROLEIRA','Um farol apagado',p.questClaimed?'A enseada está segura graças a você. Explore as rotas que se abriram.':`Afaste três saqueadores da vila (${Math.min(p.quests,3)}/3) e volte para receber sua recompensa.`)}<button class="modal-action" data-action="close">ENTENDI</button>`)}else if(n.role==='mercador')showShop();else showSkills()}

